 #define BITCOIN_UTIL_TIME_H

 // The `util/time.h` header is designed to be a drop-in replacement for `chrono`.
+#include <atomic>
 #include <chrono> // IWYU pragma: export
 #include <cstdint>
 #include <ctime>
+#include <functional>
